select public.t_assert(not has_function_privilege('anon','public.registrar_mensaje_whatsapp_qa928(bigint,text,text,text,text,timestamptz,text,text)','execute'),'anon no ejecuta RPC');
select public.t_assert(not has_function_privilege('authenticated','public.registrar_mensaje_whatsapp_qa928(bigint,text,text,text,text,timestamptz,text,text)','execute'),'authenticated no ejecuta RPC');
select public.t_assert(has_function_privilege('service_role','public.registrar_mensaje_whatsapp_qa928(bigint,text,text,text,text,timestamptz,text,text)','execute'),'service_role ejecuta RPC');
set role service_role;
do $$ declare first jsonb; replay jsonb; result jsonb; begin
  first := public.registrar_mensaje_whatsapp_qa928(48,'inbound:first','paciente','5491155550107','Hola','2026-10-09 15:00:00+00','first');
  replay := public.registrar_mensaje_whatsapp_qa928(48,'inbound:first','paciente','5491155550107','Hola','2026-10-09 15:00:00+00','first');
  perform public.t_assert(first->>'status'='persisted' and replay->>'status'='replay' and first#>>'{mensaje,id}'=replay#>>'{mensaje,id}','mismo evento no duplica mensaje');
  perform public.t_assert(first#>>'{cliente,whatsapp_nombre_pendiente}'='true','nuevo cliente queda sin nombre confirmado');
  perform public.t_assert(first#>>'{mensaje,hora}'='12:00' and first#>>'{mensaje,enviado_wsp}'='false' and first#>>'{mensaje,leido}'='false','fecha BA e ingreso no leído/no enviado');
  result := public.registrar_mensaje_whatsapp_qa928(48,'agent-outbound:first','bot','5491155550107','¿A nombre de quién?','2026-10-09 15:00:01+00','provider-first');
  perform public.t_assert(result#>>'{mensaje,estado_envio}'='aceptado' and result#>>'{mensaje,whatsapp_id}'='provider-first','respuesta aceptada con identidad, no entrega inventada');
  begin perform public.registrar_mensaje_whatsapp_qa928(48,'agent-outbound:first','bot','5491155550107','¿A nombre de quién?','2026-10-09 15:00:01+00','provider-other'); raise exception 'accepted provider identity conflict'; exception when invalid_parameter_value then null; end;
  perform public.t_assert(first#>>'{cliente,id}'=result#>>'{cliente,id}','misma ficha para ingreso y respuesta');
  result := public.registrar_mensaje_whatsapp_qa928(48,'inbound:name','paciente','5491155550107','Soy Ana','2026-10-09 15:00:02+00','name','Ana');
  perform public.t_assert(result#>>'{cliente,nombre}'='Ana' and result#>>'{cliente,whatsapp_nombre_pendiente}'='false','nombre válido promueve la ficha provisional');
  result := public.registrar_mensaje_whatsapp_qa928(48,'inbound:other-name','paciente','5491155550107','Soy Elena','2026-10-09 15:00:03+00','other-name','Elena');
  perform public.t_assert(result#>>'{cliente,nombre}'='Ana','no reemplaza el nombre de una ficha real');
  begin perform public.registrar_mensaje_whatsapp_qa928(47,'inbound:foreign','paciente','5491155550107','Hola',now(),'foreign'); raise exception 'accepted foreign tenant'; exception when insufficient_privilege then null; end;
  begin perform public.registrar_mensaje_whatsapp_qa928(48,'inbound:first','paciente','5491155550107','Texto distinto',now(),'first'); raise exception 'accepted identity conflict'; exception when invalid_parameter_value then null; end;
  begin perform public.registrar_mensaje_whatsapp_qa928(48,'agent-outbound:missing-id','bot','5491155550107','Hola',now(),null); raise exception 'accepted missing provider id'; exception when invalid_parameter_value then null; end;
  begin perform public.registrar_mensaje_whatsapp_qa928(48,'inbound:invalid-phone','paciente','abc','Hola',now(),'invalid-phone'); raise exception 'accepted invalid phone'; exception when invalid_parameter_value then null; end;
  begin perform public.registrar_mensaje_whatsapp_qa928(48,'inbound:invalid-date','paciente','5491155550107','Hola','infinity','invalid-date'); raise exception 'accepted infinite timestamp'; exception when invalid_parameter_value then null; end;
end $$;
reset role;
select public.t_assert((select count(*)=1 from public.clientes where barberia_id=928 and telefono='5491155550107'),'una sola ficha por teléfono');
select public.t_assert((select count(*)=0 from public.mensajes where barberia_id=927),'ninguna escritura en otro tenant');
select public.t_assert((select valor='false' from public.config where barberia_id=928 and clave='bot_activo'),'persistir no cambia pausa del bot');
select public.t_assert((select bool_and(relrowsecurity) from pg_class where oid in ('public.clientes'::regclass,'public.mensajes'::regclass)),'RLS sigue habilitado');
update public.saas_integraciones set external_instance_id='miwsp' where id=48;
set role service_role;
do $$ begin begin perform public.registrar_mensaje_whatsapp_qa928(48,'inbound:wrong-instance','paciente','5491155550107','Hola',now(),'wrong-instance'); raise exception 'accepted wrong instance'; exception when insufficient_privilege then null; end; end $$;
reset role;
update public.saas_integraciones set external_instance_id='austral-qa-tenant-928' where id=48;
set role authenticated;
select public.t_assert((select count(*)=0 from public.clientes),'RLS conserva aislamiento del fixture');
reset role;
select 'SQL funcional y permisos PASS' as resultado;
